def shingles(text, n):
    w = text.lower().split()
    if len(w) < n:
        return set()
    return {' '.join(w[i:i + n]) for i in range(len(w) - n + 1)}

def jaccard(a, b):
    u = a | b
    if not u:
        return 0.0
    return len(a & b) / len(u)
